import { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { getCheckinsByCliente } from '../../data/store';
import type { Checkin } from '../../types';
import { ClipboardCheck, TrendingUp, TrendingDown, Minus } from 'lucide-react';

export default function AlunoCheckins() {
  const { user } = useAuth();
  const [checkins, setCheckins] = useState<Checkin[]>([]);

  useEffect(() => {
    if (user?.id) {
      setCheckins(getCheckinsByCliente(user.id).sort((a, b) => new Date(b.data).getTime() - new Date(a.data).getTime()));
    }
  }, [user]);

  const humorEmoji: Record<string, string> = { otimo: '­ƒÿü', bom: '­ƒÿè', regular: '­ƒÿÉ', ruim: '­ƒÿ×' };

  const getTrend = (current: string, previous: string) => {
    const c = parseFloat(current);
    const p = parseFloat(previous);
    if (isNaN(c) || isNaN(p)) return null;
    if (c > p) return 'up';
    if (c < p) return 'down';
    return 'same';
  };

  const TrendIcon = ({ trend }: { trend: string | null }) => {
    if (!trend) return null;
    if (trend === 'up') return <TrendingUp size={12} style={{ color: '#10b981' }} />;
    if (trend === 'down') return <TrendingDown size={12} style={{ color: '#ef4444' }} />;
    return <Minus size={12} style={{ color: 'var(--text-muted)' }} />;
  };

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <h1>Minha Evolu├º├úo</h1>
        <p>Acompanhe seu progresso ao longo do tempo</p>
      </div>

      {checkins.length === 0 ? (
        <div className="card">
          <div className="empty-state">
            <ClipboardCheck />
            <h3>Nenhum check-in registrado</h3>
            <p>Seu personal trainer registrar├í seus check-ins aqui</p>
          </div>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: 16 }}>
          {checkins.map((c, i) => {
            const prev = checkins[i + 1];
            return (
              <div key={c.id} className="card animate-fadeInUp">
                <div className="card-header">
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <div className="checkin-number">#{checkins.length - i}</div>
                    <div>
                      <h2 className="card-title" style={{ marginBottom: 0, fontSize: '0.95rem' }}>
                        {new Date(c.data).toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' })}
                      </h2>
                      <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                        {humorEmoji[c.humor]} Humor: {c.humor}
                      </p>
                    </div>
                  </div>
                </div>
                <div className="checkin-grid">
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">
                      {c.peso || '-'}
                      {prev && <TrendIcon trend={getTrend(c.peso, prev.peso)} />}
                    </div>
                    <div className="checkin-metric-label">Peso (kg)</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">
                      {c.gorduraCorporal || '-'}
                      {prev && <TrendIcon trend={getTrend(c.gorduraCorporal, prev.gorduraCorporal)} />}
                    </div>
                    <div className="checkin-metric-label">% Gordura</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">
                      {c.massaMuscular || '-'}
                      {prev && <TrendIcon trend={getTrend(c.massaMuscular, prev.massaMuscular)} />}
                    </div>
                    <div className="checkin-metric-label">Massa Musc.</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">{c.bracoD || '-'}</div>
                    <div className="checkin-metric-label">Bra├ºo D</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">{c.bracoE || '-'}</div>
                    <div className="checkin-metric-label">Bra├ºo E</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">{c.cintura || '-'}</div>
                    <div className="checkin-metric-label">Cintura</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">{c.quadril || '-'}</div>
                    <div className="checkin-metric-label">Quadril</div>
                  </div>
                  <div className="checkin-metric">
                    <div className="checkin-metric-value">{c.pernaD || '-'}</div>
                    <div className="checkin-metric-label">Perna D</div>
                  </div>
                </div>
                {c.observacoes && (
                  <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', padding: '0 20px 16px', fontStyle: 'italic' }}>
                    "{c.observacoes}"
                  </p>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

